-- Italian instructions for every exercise currently approved for generated programs.
with translations as (
  select * from jsonb_to_recordset($translations$[{"legacy_key": "back_squat", "name": "Squat con bilanciere", "instructions": "Posiziona il bilanciere sulla parte alta della schiena e tieni i piedi circa alla larghezza delle spalle. Scendi piegando anche e ginocchia, mantenendo il busto stabile e la schiena in posizione neutra. Risali spingendo attraverso i piedi, con il petto sollevato.", "steps": ["Sistema il bilanciere sulla parte alta dei trapezi e staccalo dai supporti.", "Posiziona i piedi circa alla larghezza delle spalle.", "Scendi in squat mantenendo la schiena neutra.", "Raggiungi una profondità che riesci a controllare, senza dolore.", "Spingi attraverso i piedi e torna in piedi."], "short_description": "Posiziona il bilanciere sulla parte alta della schiena e tieni i piedi circa alla larghezza delle spalle."}, {"legacy_key": "bench_press", "name": "Panca piana con bilanciere", "instructions": "Sdraiati sulla panca con i piedi ben appoggiati a terra e afferra il bilanciere con una presa poco più ampia delle spalle. Staccalo dai supporti e portalo sopra il petto. Abbassalo lentamente verso la parte centrale del petto, mantenendo il controllo dei gomiti e dei polsi. Sfiora il petto senza rimbalzare, poi distendi le braccia per risalire.", "steps": ["Sdraiati con gli occhi sotto il bilanciere e i piedi saldi a terra.", "Afferra la barra poco più larga delle spalle e staccala dai supporti.", "Abbassala verso il centro del petto con i polsi allineati agli avambracci.", "Sfiora il petto, poi spingi verso l’alto fino a distendere le braccia.", "Al termine della serie accompagna il bilanciere sui supporti."], "short_description": "Sdraiati sulla panca con i piedi ben appoggiati a terra e afferra il bilanciere con una presa poco più ampia delle spalle."}, {"legacy_key": "cable_row", "name": "Rematore al cavo da seduto", "instructions": "Siediti alla postazione del rematore con i piedi sulla pedana e afferra la maniglia a V. Mantieni la schiena neutra e tira la maniglia verso il busto, avvicinando le scapole e piegando i gomiti. Torna lentamente alla posizione iniziale.", "steps": ["Siediti e appoggia i piedi sulla pedana.", "Afferra la maniglia con entrambe le mani e distendi le braccia.", "Mantieni il busto stabile e le ginocchia leggermente piegate.", "Tira la maniglia verso l’addome, avvicinando le scapole.", "Distendi lentamente le braccia senza perdere il controllo."], "short_description": "Siediti alla postazione del rematore con i piedi sulla pedana e afferra la maniglia a V."}, {"legacy_key": "dumbbell_shoulder_press", "name": "Spinte sopra la testa con manubri", "instructions": "Siediti con la schiena sostenuta dallo schienale e porta i manubri all’altezza delle spalle, con i palmi rivolti in avanti. Spingi i pesi sopra la testa fino a distendere le braccia. Riabbassali lentamente fino alla posizione iniziale.", "steps": ["Siediti su una panca con schienale e appoggia i piedi a terra.", "Porta i manubri all’altezza delle spalle con i gomiti piegati.", "Spingi i manubri sopra la testa fino a distendere le braccia.", "Fai una breve pausa in alto.", "Riporta i manubri alle spalle in modo controllato."], "short_description": "Siediti con la schiena sostenuta dallo schienale e porta i manubri all’altezza delle spalle, con i palmi rivolti in avanti."}, {"legacy_key": "incline_dumbbell_press", "name": "Spinte con manubri su panca inclinata", "instructions": "Regola la panca inclinata e siediti con un manubrio per mano. Appoggia la schiena e porta i pesi ai lati della parte alta del petto, con i palmi in avanti. Mantieni i piedi a terra e spingi i manubri verso l’alto fino a distendere le braccia. Riabbassali lentamente lungo lo stesso percorso.", "steps": ["Regola la panca inclinata e siediti con i manubri appoggiati sulle cosce.", "Appoggia la schiena e porta i manubri all’altezza del petto.", "Tieni i piedi saldi e i gomiti leggermente sotto la linea delle spalle.", "Spingi i manubri sopra la parte alta del petto.", "Riabbassali lentamente ai lati del petto.", "Ripeti mantenendo il movimento controllato."], "short_description": "Regola la panca inclinata e siediti con un manubrio per mano."}, {"legacy_key": "lat_pulldown", "name": "Lat machine davanti", "instructions": "Regola il sedile e il fermo per le cosce della lat machine. Siediti con la schiena neutra e i piedi a terra. Afferra la barra con presa prona poco più ampia delle spalle. Inclina leggermente il busto all’indietro e tira la barra verso la parte alta del petto, guidando i gomiti verso il basso. Risali lentamente senza oscillare.", "steps": ["Regola il sedile e blocca le cosce sotto il cuscino.", "Afferra la barra poco più larga delle spalle e distendi le braccia.", "Solleva il petto e abbassa le spalle lontano dalle orecchie.", "Porta i gomiti verso il basso e la barra alla parte alta del petto.", "Fai una breve pausa mantenendo il busto stabile.", "Distendi lentamente le braccia e lascia risalire la barra con controllo."], "short_description": "Regola il sedile e il fermo per le cosce della lat machine."}, {"legacy_key": "lateral_raise", "name": "Alzate laterali con manubri", "instructions": "In piedi, tieni un manubrio per mano lungo i fianchi, con i palmi verso il corpo. Mantieni il busto stabile e i gomiti leggermente piegati. Solleva le braccia lateralmente fino a circa l’altezza delle spalle, senza alzare le spalle verso le orecchie. Riabbassa lentamente i pesi.", "steps": ["Parti in piedi con i manubri lungo i fianchi.", "Mantieni le spalle basse e l’addome attivo.", "Solleva le braccia lateralmente fino all’altezza delle spalle, con i gomiti morbidi.", "Fai una breve pausa senza sollevare le spalle.", "Riporta i manubri ai fianchi in modo controllato."], "short_description": "In piedi, tieni un manubrio per mano lungo i fianchi, con i palmi verso il corpo."}, {"legacy_key": "overhead_press", "name": "Spinte sopra la testa con bilanciere", "instructions": "In piedi, tieni i piedi alla larghezza delle anche e il bilanciere all’altezza delle spalle, con presa prona. Mantieni addome e glutei attivi e spingi la barra sopra la testa fino a distendere le braccia, senza accentuare l’arco della zona lombare. Riabbassala lentamente alle spalle.", "steps": ["Parti in piedi con il bilanciere all’altezza delle spalle.", "Afferra la barra con le mani appena oltre la larghezza delle spalle.", "Attiva addome e glutei per stabilizzare il busto.", "Spingi il bilanciere sopra la testa fino a distendere le braccia.", "Riabbassalo lentamente alle spalle."], "short_description": "In piedi, tieni i piedi alla larghezza delle anche e il bilanciere all’altezza delle spalle, con presa prona."}, {"legacy_key": "plank", "name": "Plank sugli avambracci", "instructions": "Appoggia avambracci e punte dei piedi a terra, con i gomiti sotto le spalle. Attiva addome e glutei e mantieni il corpo allineato dalla testa ai talloni. Tieni la posizione per il tempo previsto, senza sollevare o lasciar cedere il bacino.", "steps": ["Posiziona gli avambracci a terra con i gomiti sotto le spalle.", "Solleva il corpo sostenendoti su avambracci e punte dei piedi.", "Allinea testa, busto e talloni.", "Attiva addome e glutei e continua a respirare.", "Mantieni la posizione per il tempo previsto, poi appoggiati a terra."], "short_description": "Appoggia avambracci e punte dei piedi a terra, con i gomiti sotto le spalle."}, {"legacy_key": "triceps_pushdown", "name": "Estensioni tricipiti al cavo", "instructions": "In piedi davanti alla postazione ai cavi, afferra la corda o la barra collegata alla carrucola alta. Tieni i gomiti vicino al busto e spingi l’impugnatura verso il basso distendendo le braccia. Torna lentamente alla posizione iniziale senza spostare i gomiti.", "steps": ["Posizionati di fronte alla carrucola alta.", "Afferra barra o corda con entrambe le mani.", "Tieni i gomiti vicini al busto.", "Spingi verso il basso fino a distendere le braccia.", "Torna lentamente alla posizione iniziale."], "short_description": "In piedi davanti alla postazione ai cavi, afferra la corda o la barra collegata alla carrucola alta."}]$translations$::jsonb)
    as t(legacy_key text, name text, instructions text, steps jsonb, short_description text)
)
insert into public.exercise_translations (exercise_id, language, name, instructions, steps, short_description)
select e.id, 'it', t.name, t.instructions, t.steps, t.short_description
from translations t join public.exercises e on e.legacy_key = t.legacy_key
on conflict (exercise_id, language) do update set
  instructions = excluded.instructions, steps = excluded.steps, short_description = excluded.short_description;
